-- FS-UX-005: property-specific Design Workspaces, governed budgets and immutable approvals.
begin;

alter table public.furnishing_projects
 add column if not exists design_workspace_status text not null default 'draft' check(design_workspace_status in('draft','designing','internal_review','customer_review','changes_requested','approved','archived')),
 add column if not exists optimistic_version bigint not null default 1 check(optimistic_version>0),
 add column if not exists source_package_id uuid references public.furnishing_packages(id),
 add column if not exists source_package_version_id uuid references public.furnishing_package_versions(id),
 add column if not exists source_package_snapshot_id uuid references public.fsux4_package_approval_snapshots(id),
 add column if not exists source_package_digest text,
 add column if not exists responsible_designer_id uuid references public.profiles(id),
 add column if not exists customer_review_required boolean not null default true,
 add column if not exists design_direction text,
 add column if not exists target_guest_profile jsonb not null default '{}'::jsonb,
 add column if not exists brief jsonb not null default '{}'::jsonb,
 add column if not exists current_design_version_id uuid,
 add column if not exists archived_at timestamptz;

create table public.fsux5_design_versions(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.furnishing_projects(id) on delete cascade,
 version_number integer not null check(version_number>0),based_on_version_id uuid references public.fsux5_design_versions(id),
 state text not null default 'draft' check(state in('draft','designing','internal_review','customer_review','changes_requested','approved','superseded')),
 optimistic_version bigint not null default 1 check(optimistic_version>0),snapshot_digest text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),approved_at timestamptz,unique(project_id,version_number)
);
alter table public.furnishing_projects add constraint furnishing_projects_current_design_version_fkey foreign key(current_design_version_id) references public.fsux5_design_versions(id);

create table public.fsux5_measurement_sets(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.furnishing_projects(id) on delete cascade,design_version_id uuid not null references public.fsux5_design_versions(id) on delete cascade,version_number integer not null check(version_number>0),source text not null,verification_status text not null check(verification_status in('unverified','customer_provided','designer_verified','professionally_verified')),measurements jsonb not null default '[]',private_media jsonb not null default '[]',provided_by uuid references public.profiles(id),captured_at timestamptz not null default now(),unique(project_id,version_number));
create table public.fsux5_mood_board_items(id uuid primary key default gen_random_uuid(),design_version_id uuid not null references public.fsux5_design_versions(id) on delete cascade,room_id uuid references public.furnishing_rooms(id),media_asset_id uuid,source_url text,source_metadata jsonb not null default '{}',caption text,customer_visible_note text,internal_note text,sort_order integer not null check(sort_order>=0),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(design_version_id,sort_order));

alter table public.furnishing_rooms add column if not exists design_version_id uuid references public.fsux5_design_versions(id),add column if not exists source_package_room_id uuid references public.fsux4_package_rooms(id),add column if not exists intended_occupancy integer check(intended_occupancy is null or intended_occupancy>=0),add column if not exists sleeping_capacity integer not null default 0 check(sleeping_capacity>=0),add column if not exists measurements jsonb not null default '{}',add column if not exists room_objectives text,add column if not exists placement_guidance text,add column if not exists archived_at timestamptz;

alter table public.furnishing_product_selections add column if not exists design_version_id uuid references public.fsux5_design_versions(id),add column if not exists product_version_id uuid references public.furnishing_product_versions(id),add column if not exists source_package_item_id uuid references public.fsux4_package_items(id),add column if not exists replaced_selection_id uuid references public.furnishing_product_selections(id),add column if not exists selection_role text not null default 'primary' check(selection_role in('primary','alternative','existing_item_retained','customer_provided','excluded','unresolved_requirement')),add column if not exists priority text not null default 'essential' check(priority in('essential','recommended','optional')),add column if not exists placement_guidance text,add column if not exists customer_rationale text,add column if not exists internal_rationale text,add column if not exists price_source text,add column if not exists optimistic_version bigint not null default 1 check(optimistic_version>0),add column if not exists correlation_id text;
-- Unresolved package requirements deliberately have no catalog selection yet.
alter table public.furnishing_product_selections alter column furnishing_plan_id drop not null;

alter table public.furnishing_budgets drop constraint if exists furnishing_budgets_project_id_key;
alter table public.furnishing_budgets add column if not exists design_version_id uuid references public.fsux5_design_versions(id),add column if not exists version_number integer not null default 1 check(version_number>0),add column if not exists based_on_budget_id uuid references public.furnishing_budgets(id),add column if not exists lifecycle_status text not null default 'draft' check(lifecycle_status in('draft','internal_review','customer_review','changes_requested','approved','superseded')),add column if not exists inclusion_basis text not null default 'products_delivery' check(inclusion_basis in('products_only','products_delivery','products_delivery_assembly','complete_installed','custom')),add column if not exists target_minimum_minor bigint check(target_minimum_minor is null or target_minimum_minor>=0),add column if not exists target_maximum_minor bigint check(target_maximum_minor is null or target_maximum_minor>=0),add column if not exists product_subtotal_minor bigint not null default 0,add column if not exists delivery_minor bigint not null default 0,add column if not exists tax_minor bigint not null default 0,add column if not exists assembly_minor bigint not null default 0,add column if not exists installation_minor bigint not null default 0,add column if not exists disposal_minor bigint not null default 0,add column if not exists design_fee_minor bigint not null default 0,add column if not exists discount_minor bigint not null default 0,add column if not exists credit_minor bigint not null default 0,add column if not exists contingency_minor bigint not null default 0,add column if not exists estimated_total_minor bigint not null default 0,add column if not exists calculation jsonb not null default '{}',add column if not exists optimistic_version bigint not null default 1,add column if not exists approved_at timestamptz;
create unique index fsux5_budget_project_version_unique on public.furnishing_budgets(project_id,version_number);

create table public.fsux5_review_events(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.furnishing_projects(id),design_version_id uuid not null references public.fsux5_design_versions(id),budget_id uuid references public.furnishing_budgets(id),stage text not null check(stage in('internal','customer','offline_customer')),decision text not null check(decision in('submitted','approved','changes_requested')),reason text,customer_identity uuid references public.profiles(id),recording_actor uuid not null references public.profiles(id),evidence_reference text,correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(project_id,idempotency_key));
create table public.fsux5_approval_snapshots(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.furnishing_projects(id),design_version_id uuid not null references public.fsux5_design_versions(id),budget_id uuid not null references public.furnishing_budgets(id),property_id uuid not null references public.properties(id),snapshot jsonb not null,snapshot_digest text not null,approved_by uuid not null references public.profiles(id),customer_approval_event_id uuid references public.fsux5_review_events(id),correlation_id text not null,created_at timestamptz not null default now(),unique(project_id,design_version_id));
create table public.fsux5_procurement_handoffs(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.furnishing_projects(id),approval_snapshot_id uuid not null references public.fsux5_approval_snapshots(id),payload jsonb not null,payload_digest text not null,prepared_by uuid not null references public.profiles(id),correlation_id text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(project_id,idempotency_key));
create table public.fsux5_activity(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.furnishing_projects(id),design_version_id uuid references public.fsux5_design_versions(id),event_type text not null,evidence jsonb not null default '{}',actor_id uuid not null references public.profiles(id),correlation_id text not null,created_at timestamptz not null default now());

create index fsux5_projects_library on public.furnishing_projects(workspace_id,design_workspace_status,updated_at desc);
create index fsux5_versions_project on public.fsux5_design_versions(project_id,version_number desc);
create index fsux5_selections_version on public.furnishing_product_selections(design_version_id,room_id);
create index fsux5_budgets_project on public.furnishing_budgets(project_id,lifecycle_status,version_number desc);

create function public.fsux5_assert_actor(w uuid) returns uuid language plpgsql security definer set search_path=public as $$declare a uuid:=auth.uid();begin if a is null or not(public.is_admin() or public.active_workspace_role(w) in('owner','administrator','operator','contributor')) then raise exception 'DESIGN_WORKSPACE_ACCESS_DENIED' using errcode='42501';end if;return a;end$$;

create function public.fsux5_create_design_workspace(w uuid,property uuid,name text,package_snapshot uuid,profile jsonb,budget jsonb,idempotency text,correlation text) returns jsonb language plpgsql security definer set search_path=public as $$declare a uuid;p public.properties;existing public.furnishing_projects;project_id uuid;version_id uuid;budget_id uuid;pkg public.fsux4_package_approval_snapshots;begin a:=public.fsux5_assert_actor(w);select * into p from public.properties where id=property and owner_id=w for update;if not found then raise exception 'DESIGN_PROPERTY_ACCESS_DENIED';end if;select * into existing from public.furnishing_projects where workspace_id=w and property_id=property and scope->>'fsux5_idempotency'=idempotency;if found then return jsonb_build_object('project_id',existing.id,'idempotent',true);end if;if package_snapshot is not null then select s.* into pkg from public.fsux4_package_approval_snapshots s join public.furnishing_packages fp on fp.id=s.package_id where s.id=package_snapshot and fp.workspace_id=w and fp.lifecycle_status='approved';if not found then raise exception 'DESIGN_PACKAGE_NOT_ELIGIBLE';end if;end if;insert into public.furnishing_projects(workspace_id,property_id,name,status,phase,lifecycle_status,design_workspace_status,source_package_id,source_package_version_id,source_package_snapshot_id,source_package_digest,target_budget_minor,target_budget_currency,brief,scope,created_by) values(w,property,name,'draft','design','designing','designing',pkg.package_id,pkg.package_version_id,package_snapshot,pkg.snapshot_hash,(budget->>'target_maximum_minor')::bigint,coalesce(budget->>'currency','USD'),profile,jsonb_build_object('fsux5_idempotency',idempotency),a) returning id into project_id;insert into public.fsux5_design_versions(project_id,version_number,state,created_by)values(project_id,1,'designing',a)returning id into version_id;update public.furnishing_projects set current_design_version_id=version_id where id=project_id;insert into public.furnishing_budgets(project_id,design_version_id,target_amount_minor,target_minimum_minor,target_maximum_minor,currency,inclusion_basis,version_number)values(project_id,version_id,coalesce((budget->>'target_maximum_minor')::bigint,0),(budget->>'target_minimum_minor')::bigint,(budget->>'target_maximum_minor')::bigint,coalesce(budget->>'currency','USD'),coalesce(budget->>'inclusion_basis','products_delivery'),1)returning id into budget_id;insert into public.property_capability_enrollments(workspace_id,property_id,capability,status,source,created_by,enabled_at)values(w,property,'furnishing','enabled','design_workspace',a,now())on conflict(property_id,capability)do nothing;if package_snapshot is not null then insert into public.furnishing_rooms(project_id,design_version_id,room_type,name,sort_order,status,source_package_room_id)select project_id,version_id,r.canonical_room_type,r.display_name,r.sort_order,'planning',r.id from public.fsux4_package_rooms r where r.package_version_id=pkg.package_version_id;insert into public.furnishing_product_selections(furnishing_plan_id,room_id,design_version_id,product_id,product_version_id,source_package_item_id,resolved_quantity,estimated_unit_price_minor,estimated_total_minor,currency,selection_source,selection_status,required,priority,placement_guidance,correlation_id)select null,r2.id,version_id,i.product_id,i.product_version_id,i.id,i.quantity,i.unit_price_minor,case when i.unit_price_minor is null then null else i.unit_price_minor*i.quantity end,coalesce(i.currency,'USD'),'package',case when i.product_id is null then 'recommended' else 'selected'end,i.fulfillment_required,i.priority,i.placement_guidance,correlation from public.fsux4_package_items i join public.furnishing_rooms r2 on r2.design_version_id=version_id and r2.source_package_room_id=i.package_room_id where i.package_version_id=pkg.package_version_id;end if;insert into public.fsux5_activity(project_id,design_version_id,event_type,evidence,actor_id,correlation_id)values(project_id,version_id,'design_workspace_created',jsonb_build_object('property_id',property,'package_snapshot_id',package_snapshot),a,correlation);return jsonb_build_object('project_id',project_id,'design_version_id',version_id,'budget_id',budget_id,'idempotent',false);end$$;

-- Replace the legacy-column implementation above with the current canonical aggregate.
create or replace function public.fsux5_create_design_workspace(w uuid,property uuid,name text,package_snapshot uuid,profile jsonb,budget jsonb,idempotency text,correlation text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare a uuid;p public.properties;existing public.furnishing_projects;project_id uuid;version_id uuid;budget_id uuid;pkg public.fsux4_package_approval_snapshots;
begin
 a:=public.fsux5_assert_actor(w);select * into p from public.properties where id=property and owner_id=w for update;if not found then raise exception 'DESIGN_PROPERTY_ACCESS_DENIED';end if;
 select * into existing from public.furnishing_projects where workspace_id=w and property_id=property and scope->>'fsux5_idempotency'=idempotency;if found then return jsonb_build_object('project_id',existing.id,'idempotent',true);end if;
 if package_snapshot is not null then select s.* into pkg from public.fsux4_package_approval_snapshots s join public.furnishing_packages fp on fp.id=s.package_id where s.id=package_snapshot and fp.workspace_id=w and fp.lifecycle_status='approved';if not found then raise exception 'DESIGN_PACKAGE_NOT_ELIGIBLE';end if;end if;
 insert into public.furnishing_projects(workspace_id,property_id,name,lifecycle_status,design_workspace_status,source_package_id,source_package_version_id,source_package_snapshot_id,source_package_digest,target_budget_minor,target_budget_currency,brief,scope,created_by)
 values(w,property,name,'designing','designing',pkg.package_id,pkg.package_version_id,package_snapshot,pkg.snapshot_hash,(budget->>'target_maximum_minor')::bigint,coalesce(budget->>'currency','USD'),profile,jsonb_build_object('fsux5_idempotency',idempotency),a)returning id into project_id;
 insert into public.fsux5_design_versions(project_id,version_number,state,created_by)values(project_id,1,'designing',a)returning id into version_id;update public.furnishing_projects set current_design_version_id=version_id where id=project_id;
 insert into public.furnishing_budgets(project_id,design_version_id,target_amount_minor,target_minimum_minor,target_maximum_minor,currency,inclusion_basis,version_number)values(project_id,version_id,coalesce((budget->>'target_maximum_minor')::bigint,0),(budget->>'target_minimum_minor')::bigint,(budget->>'target_maximum_minor')::bigint,coalesce(budget->>'currency','USD'),coalesce(budget->>'inclusion_basis','products_delivery'),1)returning id into budget_id;
 insert into public.property_capability_enrollments(workspace_id,property_id,capability,status,source,created_by,enabled_at)values(w,property,'furnishing','enabled','studio',a,now())on conflict(property_id,capability)do nothing;
 if package_snapshot is not null then insert into public.furnishing_rooms(project_id,design_version_id,room_type,name,sort_order,status,source_package_room_id)select project_id,version_id,r.canonical_room_type,r.display_name,r.sort_order,'planning',r.id from public.fsux4_package_rooms r where r.package_version_id=pkg.package_version_id;end if;
 insert into public.fsux5_activity(project_id,design_version_id,event_type,evidence,actor_id,correlation_id)values(project_id,version_id,'design_workspace_created',jsonb_build_object('property_id',property,'package_snapshot_id',package_snapshot),a,correlation);
 return jsonb_build_object('project_id',project_id,'design_version_id',version_id,'budget_id',budget_id,'idempotent',false);
end$$;

-- Final approval snapshots both compatible versions in one locked transaction.
create function public.fsux5_approve_design(project uuid,expected bigint,customer_event uuid,idempotency text,correlation text) returns jsonb language plpgsql security definer set search_path=public as $$declare p public.furnishing_projects;v public.fsux5_design_versions;b public.furnishing_budgets;a uuid;s jsonb;sid uuid;begin select * into p from public.furnishing_projects where id=project for update;if not found then raise exception 'DESIGN_WORKSPACE_NOT_FOUND';end if;a:=public.fsux5_assert_actor(p.workspace_id);select * into v from public.fsux5_design_versions where id=p.current_design_version_id and optimistic_version=expected for update;if not found then raise exception 'DESIGN_WORKSPACE_STALE';end if;select * into b from public.furnishing_budgets where design_version_id=v.id and lifecycle_status in('internal_review','customer_review') for update;if not found then raise exception 'DESIGN_BUDGET_NOT_REVIEWABLE';end if;if p.customer_review_required and not exists(select 1 from public.fsux5_review_events e where e.id=customer_event and e.project_id=project and e.design_version_id=v.id and e.budget_id=b.id and e.stage in('customer','offline_customer') and e.decision='approved')then raise exception 'CUSTOMER_APPROVAL_REQUIRED';end if;if exists(select 1 from public.fsux5_approval_snapshots x where x.project_id=project and x.design_version_id=v.id)then select id into sid from public.fsux5_approval_snapshots where project_id=project and design_version_id=v.id;return jsonb_build_object('snapshot_id',sid,'idempotent',true);end if;s:=jsonb_build_object('property_id',p.property_id,'project',to_jsonb(p),'design_version',to_jsonb(v),'budget',to_jsonb(b),'rooms',coalesce((select jsonb_agg(to_jsonb(r)order by r.sort_order)from public.furnishing_rooms r where r.design_version_id=v.id),'[]'::jsonb),'selections',coalesce((select jsonb_agg(to_jsonb(x)order by x.id)from public.furnishing_product_selections x where x.design_version_id=v.id),'[]'::jsonb),'measurements',coalesce((select jsonb_agg(to_jsonb(m)order by m.version_number)from public.fsux5_measurement_sets m where m.design_version_id=v.id),'[]'::jsonb),'mood_board',coalesce((select jsonb_agg(to_jsonb(m)order by m.sort_order)from public.fsux5_mood_board_items m where m.design_version_id=v.id),'[]'::jsonb));insert into public.fsux5_approval_snapshots(project_id,design_version_id,budget_id,property_id,snapshot,snapshot_digest,approved_by,customer_approval_event_id,correlation_id)values(project,v.id,b.id,p.property_id,s,encode(extensions.digest(s::text,'sha256'),'hex'),a,customer_event,correlation)returning id into sid;update public.fsux5_design_versions set state='approved',approved_at=now(),snapshot_digest=encode(extensions.digest(s::text,'sha256'),'hex')where id=v.id;update public.furnishing_budgets set lifecycle_status='approved',status='approved',approved_at=now()where id=b.id;update public.furnishing_projects set design_workspace_status='approved',lifecycle_status='approved',optimistic_version=optimistic_version+1 where id=project;return jsonb_build_object('snapshot_id',sid,'idempotent',false);end$$;

create function public.fsux5_prepare_procurement_handoff(project uuid,idempotency text,correlation text) returns jsonb language plpgsql security definer set search_path=public as $$declare p public.furnishing_projects;a uuid;s public.fsux5_approval_snapshots;existing public.fsux5_procurement_handoffs;payload jsonb;hid uuid;begin select * into p from public.furnishing_projects where id=project and design_workspace_status='approved';if not found then raise exception 'DESIGN_NOT_APPROVED';end if;a:=public.fsux5_assert_actor(p.workspace_id);select * into existing from public.fsux5_procurement_handoffs where project_id=project and idempotency_key=idempotency;if found then return jsonb_build_object('handoff_id',existing.id,'idempotent',true);end if;select * into s from public.fsux5_approval_snapshots where project_id=project order by created_at desc limit 1;if not found then raise exception 'DESIGN_SNAPSHOT_REQUIRED';end if;payload:=jsonb_build_object('design_snapshot_id',s.id,'design_version_id',s.design_version_id,'budget_id',s.budget_id,'prepared_only',true);insert into public.fsux5_procurement_handoffs(project_id,approval_snapshot_id,payload,payload_digest,prepared_by,correlation_id,idempotency_key)values(project,s.id,payload,encode(extensions.digest(payload::text,'sha256'),'hex'),a,correlation,idempotency)returning id into hid;return jsonb_build_object('handoff_id',hid,'idempotent',false,'external_effects',false);end$$;

create or replace function public.fsux5_approve_design(project uuid,expected bigint,customer_event uuid,idempotency text,correlation text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.furnishing_projects;v public.fsux5_design_versions;b public.furnishing_budgets;a uuid;s jsonb;sid uuid;
begin
 select * into p from public.furnishing_projects where id=project for update;if not found then raise exception 'DESIGN_WORKSPACE_NOT_FOUND';end if;a:=public.fsux5_assert_actor(p.workspace_id);
 select * into v from public.fsux5_design_versions where id=p.current_design_version_id and optimistic_version=expected for update;if not found then raise exception 'DESIGN_WORKSPACE_STALE';end if;
 select id into sid from public.fsux5_approval_snapshots where project_id=project and design_version_id=v.id;if found then return jsonb_build_object('snapshot_id',sid,'idempotent',true);end if;
 select * into b from public.furnishing_budgets where design_version_id=v.id and lifecycle_status in('internal_review','customer_review')for update;if not found then raise exception 'DESIGN_BUDGET_NOT_REVIEWABLE';end if;
 if p.customer_review_required and not exists(select 1 from public.fsux5_review_events e where e.id=customer_event and e.project_id=project and e.design_version_id=v.id and e.budget_id=b.id and e.stage in('customer','offline_customer')and e.decision='approved')then raise exception 'CUSTOMER_APPROVAL_REQUIRED';end if;
 s:=jsonb_build_object('property_id',p.property_id,'project',to_jsonb(p),'design_version',to_jsonb(v),'budget',to_jsonb(b),'rooms',coalesce((select jsonb_agg(to_jsonb(r)order by r.sort_order)from public.furnishing_rooms r where r.design_version_id=v.id),'[]'::jsonb),'selections',coalesce((select jsonb_agg(to_jsonb(x)order by x.id)from public.furnishing_product_selections x where x.design_version_id=v.id),'[]'::jsonb),'measurements',coalesce((select jsonb_agg(to_jsonb(m)order by m.version_number)from public.fsux5_measurement_sets m where m.design_version_id=v.id),'[]'::jsonb),'mood_board',coalesce((select jsonb_agg(to_jsonb(m)order by m.sort_order)from public.fsux5_mood_board_items m where m.design_version_id=v.id),'[]'::jsonb));
 insert into public.fsux5_approval_snapshots(project_id,design_version_id,budget_id,property_id,snapshot,snapshot_digest,approved_by,customer_approval_event_id,correlation_id)values(project,v.id,b.id,p.property_id,s,encode(extensions.digest(s::text,'sha256'),'hex'),a,customer_event,correlation)returning id into sid;
 update public.fsux5_design_versions set state='approved',approved_at=now(),snapshot_digest=encode(extensions.digest(s::text,'sha256'),'hex')where id=v.id;update public.furnishing_budgets set lifecycle_status='approved',status='approved',approved_at=now()where id=b.id;update public.furnishing_projects set design_workspace_status='approved',lifecycle_status='approved',optimistic_version=optimistic_version+1 where id=project;
 return jsonb_build_object('snapshot_id',sid,'idempotent',false);
end$$;

create function public.fsux5_prevent_immutable_mutation() returns trigger language plpgsql set search_path=public as $$begin raise exception 'DESIGN_APPROVAL_EVIDENCE_IMMUTABLE';end$$;
create trigger fsux5_snapshot_immutable before update or delete on public.fsux5_approval_snapshots for each row execute function public.fsux5_prevent_immutable_mutation();

alter table public.fsux5_design_versions enable row level security;alter table public.fsux5_measurement_sets enable row level security;alter table public.fsux5_mood_board_items enable row level security;alter table public.fsux5_review_events enable row level security;alter table public.fsux5_approval_snapshots enable row level security;alter table public.fsux5_procurement_handoffs enable row level security;alter table public.fsux5_activity enable row level security;
create policy "Members read design versions" on public.fsux5_design_versions for select to authenticated using(exists(select 1 from public.furnishing_projects p where p.id=project_id and (public.active_workspace_role(p.workspace_id)is not null or public.is_admin())));
create policy "Members read measurements" on public.fsux5_measurement_sets for select to authenticated using(exists(select 1 from public.furnishing_projects p where p.id=project_id and (public.active_workspace_role(p.workspace_id)is not null or public.is_admin())));
create policy "Members read mood boards" on public.fsux5_mood_board_items for select to authenticated using(exists(select 1 from public.fsux5_design_versions v join public.furnishing_projects p on p.id=v.project_id where v.id=design_version_id and (public.active_workspace_role(p.workspace_id)is not null or public.is_admin())));
create policy "Members read design reviews" on public.fsux5_review_events for select to authenticated using(exists(select 1 from public.furnishing_projects p where p.id=project_id and (public.active_workspace_role(p.workspace_id)is not null or public.is_admin())));
create policy "Members read design snapshots" on public.fsux5_approval_snapshots for select to authenticated using(exists(select 1 from public.furnishing_projects p where p.id=project_id and (public.active_workspace_role(p.workspace_id)is not null or public.is_admin())));
create policy "Members read handoffs" on public.fsux5_procurement_handoffs for select to authenticated using(exists(select 1 from public.furnishing_projects p where p.id=project_id and (public.active_workspace_role(p.workspace_id)is not null or public.is_admin())));
create policy "Members read design activity" on public.fsux5_activity for select to authenticated using(exists(select 1 from public.furnishing_projects p where p.id=project_id and (public.active_workspace_role(p.workspace_id)is not null or public.is_admin())));
revoke all on public.fsux5_design_versions,public.fsux5_measurement_sets,public.fsux5_mood_board_items,public.fsux5_review_events,public.fsux5_approval_snapshots,public.fsux5_procurement_handoffs,public.fsux5_activity from public,anon,authenticated;
grant select on public.fsux5_design_versions,public.fsux5_measurement_sets,public.fsux5_mood_board_items,public.fsux5_review_events,public.fsux5_approval_snapshots,public.fsux5_procurement_handoffs,public.fsux5_activity to authenticated;
revoke all on function public.fsux5_assert_actor(uuid),public.fsux5_create_design_workspace(uuid,uuid,text,uuid,jsonb,jsonb,text,text),public.fsux5_approve_design(uuid,bigint,uuid,text,text),public.fsux5_prepare_procurement_handoff(uuid,text,text) from public,anon;
grant execute on function public.fsux5_create_design_workspace(uuid,uuid,text,uuid,jsonb,jsonb,text,text),public.fsux5_approve_design(uuid,bigint,uuid,text,text),public.fsux5_prepare_procurement_handoff(uuid,text,text) to authenticated;

commit;
